// Exact Salesforce-admitted source,14 named lifecycle methods and original APIs.
func TestRunMapPutErrorLifecycle(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2ThrowKey.cls"), "public class GladeB2ThrowKey {\n    public class MarkerException extends Exception {}\n    public Boolean failHash = false;\n    public Boolean failEquals = false;\n    public String value;\n    public GladeB2ThrowKey(String text) { value = text; }\n    public Integer hashCode() {\n        if (failHash) { throw new MarkerException('owned hash marker'); }\n        return 7;\n    }\n    public Boolean equals(Object other) {\n        if (failEquals) { throw new MarkerException('owned equals marker'); }\n        return other instanceof GladeB2ThrowKey && value == ((GladeB2ThrowKey)other).value;\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2ThrowKey.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>65.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2PutLifecycleObservationTest.cls"), "@IsTest private class GladeB2PutLifecycleObservationTest {\n    private static void observe(String view, Boolean hashFailure) {\n        GladeB2ThrowKey stored = new GladeB2ThrowKey('stored');\n        GladeB2ThrowKey lookup = new GladeB2ThrowKey('different');\n        Map<GladeB2ThrowKey,String> values = new Map<GladeB2ThrowKey,String>{stored => 'ORIGINAL'};\n        stored.failEquals = !hashFailure;\n        lookup.failEquals = !hashFailure;\n        lookup.failHash = hashFailure;\n        Boolean caught = false;\n        String observedType;\n        String observedMessage;\n        try { values.put(lookup, 'NEW'); }\n        catch (Exception error) {\n            caught = true;\n            observedType = error.getTypeName();\n            observedMessage = error.getMessage();\n        }\n        System.assertEquals(true, caught);\n        System.assertEquals('GladeB2ThrowKey.MarkerException', observedType);\n        System.assertEquals(hashFailure ? 'owned hash marker' : 'owned equals marker', observedMessage);\n        System.assertEquals(2, values.size());\n        stored.failHash = false;\n        stored.failEquals = false;\n        lookup.failHash = false;\n        lookup.failEquals = false;\n        String observed = 'beforeSize=' + values.size();\n        String phase = view;\n        try {\n            if (view == 'keySet') {\n                Set<GladeB2ThrowKey> keys = values.keySet();\n                List<String> texts = new List<String>();\n                for (GladeB2ThrowKey key : keys) texts.add(key.value);\n                texts.sort();\n                observed += ';keyCount=' + keys.size() + ';keys=' + JSON.serialize(texts);\n            } else if (view == 'values') {\n                List<String> items = values.values();\n                items.sort();\n                observed += ';valueCount=' + items.size() + ';values=' + JSON.serialize(items);\n            } else if (view == 'getStored') {\n                observed += ';result=' + JSON.serialize(values.get(stored));\n            } else if (view == 'getLookup') {\n                observed += ';result=' + JSON.serialize(values.get(lookup));\n            } else if (view == 'containsStored') {\n                observed += ';result=' + values.containsKey(stored);\n            } else if (view == 'containsLookup') {\n                observed += ';result=' + values.containsKey(lookup);\n            } else if (view == 'removeLookup') {\n                observed += ';result=' + JSON.serialize(values.remove(lookup));\n            }\n            observed += ';afterSize=' + values.size();\n            phase = 'complete';\n        } catch (Exception error) {\n            observed += ';error=' + error.getTypeName() + ': ' + error.getMessage();\n        }\n        System.assertEquals('complete', phase);\n        if (view == 'containsLookup' && hashFailure == false) System.assertEquals('beforeSize=2;result=true;afterSize=2', observed);\n        if (view == 'containsLookup' && hashFailure == true) System.assertEquals('beforeSize=2;result=false;afterSize=2', observed);\n        if (view == 'containsStored' && hashFailure == false) System.assertEquals('beforeSize=2;result=true;afterSize=2', observed);\n        if (view == 'containsStored' && hashFailure == true) System.assertEquals('beforeSize=2;result=true;afterSize=2', observed);\n        if (view == 'getLookup' && hashFailure == false) System.assertEquals('beforeSize=2;result=\"NEW\";afterSize=2', observed);\n        if (view == 'getLookup' && hashFailure == true) System.assertEquals('beforeSize=2;result=null;afterSize=2', observed);\n        if (view == 'getStored' && hashFailure == false) System.assertEquals('beforeSize=2;result=\"ORIGINAL\";afterSize=2', observed);\n        if (view == 'getStored' && hashFailure == true) System.assertEquals('beforeSize=2;result=\"ORIGINAL\";afterSize=2', observed);\n        if (view == 'keySet' && hashFailure == false) System.assertEquals('beforeSize=2;keyCount=2;keys=[\"different\",\"stored\"];afterSize=2', observed);\n        if (view == 'keySet' && hashFailure == true) System.assertEquals('beforeSize=2;keyCount=2;keys=[\"different\",\"stored\"];afterSize=2', observed);\n        if (view == 'removeLookup' && hashFailure == false) System.assertEquals('beforeSize=2;result=\"NEW\";afterSize=1', observed);\n        if (view == 'removeLookup' && hashFailure == true) System.assertEquals('beforeSize=2;result=null;afterSize=2', observed);\n        if (view == 'values' && hashFailure == false) System.assertEquals('beforeSize=2;valueCount=2;values=[\"NEW\",\"ORIGINAL\"];afterSize=2', observed);\n        if (view == 'values' && hashFailure == true) System.assertEquals('beforeSize=2;valueCount=2;values=[\"NEW\",\"ORIGINAL\"];afterSize=2', observed);\n    }\n    @IsTest static void keySetAfterPutHashFailure() { observe('keySet', true); }\n    @IsTest static void valuesAfterPutHashFailure() { observe('values', true); }\n    @IsTest static void getStoredAfterPutHashFailure() { observe('getStored', true); }\n    @IsTest static void getLookupAfterPutHashFailure() { observe('getLookup', true); }\n    @IsTest static void containsStoredAfterPutHashFailure() { observe('containsStored', true); }\n    @IsTest static void containsLookupAfterPutHashFailure() { observe('containsLookup', true); }\n    @IsTest static void removeLookupAfterPutHashFailure() { observe('removeLookup', true); }\n    @IsTest static void keySetAfterPutEqualsFailure() { observe('keySet', false); }\n    @IsTest static void valuesAfterPutEqualsFailure() { observe('values', false); }\n    @IsTest static void getStoredAfterPutEqualsFailure() { observe('getStored', false); }\n    @IsTest static void getLookupAfterPutEqualsFailure() { observe('getLookup', false); }\n    @IsTest static void containsStoredAfterPutEqualsFailure() { observe('containsStored', false); }\n    @IsTest static void containsLookupAfterPutEqualsFailure() { observe('containsLookup', false); }\n    @IsTest static void removeLookupAfterPutEqualsFailure() { observe('removeLookup', false); }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2PutLifecycleObservationTest.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>60.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"65.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 14 || got.Passed != 14 {
		data, _ := json.Marshal(run)
		t.Fatalf("admitted contract failed: %s", data)
	}
}
